// ===== Selecionar vencidas =====
function selecionar(configItems, msgItems, agora) {
  const cfg = {};
  for (const i of configItems) { const r = i.json || i; if (r && r.chave) cfg[r.chave] = { valor: String(r.valor ?? '').trim(), status: String(r.status || '').toUpperCase() }; }
  const hc = (cfg.HORARIO_COMERCIAL && cfg.HORARIO_COMERCIAL.valor) || '09:00-18:00;1,2,3,4,5';
  const p = hc.split(';'); const hs = p[0].split('-');
  const min = (x) => { const q = x.split(':'); return Number(q[0]) * 60 + Number(q[1] || 0); };
  const dias = (p[1] || '1,2,3,4,5').split(',').map(Number);
  const loc = new Date(agora - 3 * 3600000);
  const dow = loc.getUTCDay() === 0 ? 7 : loc.getUTCDay();
  const m = loc.getUTCHours() * 60 + loc.getUTCMinutes();
  // Humanizado: só escreve para clientes em horário comercial
  if (!dias.includes(dow) || m < min(hs[0]) || m >= min(hs[1])) return [];
  return msgItems.map((i) => i.json || i)
    .filter((r) => r && r.id && r.status === 'AGENDADA' && Date.parse(r.agendado_para) <= agora)
    .sort((a, b) => Date.parse(a.agendado_para) - Date.parse(b.agendado_para))
    .slice(0, 8);
}


return selecionar($('Ler configuração').all(), $input.all(), Date.now()).map((r) => ({ json: r }));

// ===== Montar contexto =====
function montarContexto(e) {
  const cfg = {};
  for (const i of e.config) { const r = i.json || i; if (r && r.chave) cfg[r.chave] = { valor: String(r.valor ?? '').trim(), status: String(r.status || '').toUpperCase() }; }
  const val = (k, d) => (cfg[k] && cfg[k].valor && !/^PENDENTE/i.test(cfg[k].valor) ? cfg[k].valor : d);
  const ok = (k) => cfg[k] && cfg[k].status === 'CONFIGURADO' && cfg[k].valor && !/^PENDENTE/i.test(cfg[k].valor);
  const row = e.msg;
  const deal = e.deal && e.deal.success ? e.deal.data : null;
  const pessoa = e.pessoa && e.pessoa.success ? e.pessoa.data : null;
  const org = e.org && e.org.success ? e.org.data : null;
  const limpar = (s) => String(s || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  const cf = (ent, chave) => {
    const id = val(chave, ''); if (!ent || !id) return '';
    let x = (ent.custom_fields || {})[id]; if (x && typeof x === 'object') x = x.value !== undefined ? x.value : (x.label || JSON.stringify(x));
    return x === null || x === undefined ? '' : String(x).trim();
  };
  const base = { row_id: row.id, deal_id: row.deal_id, tipo_msg: row.tipo_msg, objetivo: row.objetivo };

  const tipo = String(row.tipo_msg || '');
  const ehPos = /^POS_/.test(tipo);
  const ehLembreteReuniao = tipo === 'LEMBRETE_VESPERA' || tipo === 'LEMBRETE_1H';
  const todas = ((e.atividades && e.atividades.data) || []);
  const pendentes = todas.filter((a) => !a.done);
  const agoraMs = e.agora || Date.now();
  const fmtQuando = (data, hora) => { const ms = Date.parse(data + 'T' + String(hora).slice(0, 5) + ':00Z') - 3 * 3600000; const d = new Date(ms); const dias = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado']; return dias[d.getUTCDay()] + ', ' + d.toISOString().slice(8, 10) + '/' + d.toISOString().slice(5, 7) + ' às ' + d.toISOString().slice(11, 16); };
  const reuniaoFutura = pendentes.filter((a) => a.type === 'meeting' && a.due_date && a.due_time && Date.parse(a.due_date + 'T' + String(a.due_time).slice(0, 5) + ':00Z') > agoraMs)
    .sort((a, b) => (a.due_date + a.due_time).localeCompare(b.due_date + b.due_time))[0];

  if (!deal) return Object.assign(base, { cancelar: true, motivo: 'Negócio não encontrado' });
  if (ehPos ? (deal.status === 'lost' || deal.status === 'deleted') : deal.status !== 'open') return Object.assign(base, { cancelar: true, motivo: 'Negócio ' + deal.status });
  if (!ehPos && !ehLembreteReuniao && Number(deal.stage_id) !== Number(row.stage_id)) return Object.assign(base, { cancelar: true, motivo: 'Card mudou de etapa antes do envio' });
  const naoContatar = cf(pessoa, 'PD_PERSON_NAO_CONTATAR');
  if (/^(sim|true|1|yes)$/i.test(naoContatar)) return Object.assign(base, { cancelar: true, motivo: 'Contato pediu para não ser contatado' });
  let reuniaoRef = null;
  if (ehLembreteReuniao) {
    const p = String(row.ref || '').split('|');
    const a = pendentes.find((x) => String(x.id) === p[0]);
    if (!a || a.due_date !== p[1] || String(a.due_time || '').slice(0, 5) !== p[2]) return Object.assign(base, { cancelar: true, motivo: 'Reunião concluída, cancelada ou remarcada' });
    reuniaoRef = a;
  }
  if (/^(FOLLOWUP_|DIAG_FUP_|ABORDAGEM_[23])/.test(tipo) && reuniaoFutura) return Object.assign(base, { cancelar: true, motivo: 'Reunião já agendada — mensagem de cobrança desnecessária' });
  if (tipo === 'ETAPA_9' && cf(deal, 'PD_DEAL_PROPOSTA_LINK')) return Object.assign(base, { cancelar: true, motivo: 'Proposta já enviada' });

  const telefone = pessoa && Array.isArray(pessoa.phones) && pessoa.phones.length ? String((pessoa.phones.find((p) => p.primary) || pessoa.phones[0]).value || '') : '';
  const nomeCompleto = pessoa ? String(pessoa.name || '').trim() : '';
  const primeiroNome = nomeCompleto.split(/\s+/)[0] || '';
  const notas = ((e.notas && e.notas.data) || []).slice(0, 12).map((n) => '- ' + String(n.add_time || '').slice(0, 10) + ': ' + limpar(n.content).slice(0, 900)).join('\n');
  const feitas = todas.filter((a) => a.done && !String(a.subject || '').startsWith('[Funil]')).slice(0, 15)
    .map((a) => '- ' + String(a.due_date || '') + ' ' + (a.type || '') + ': ' + limpar(a.subject) + (a.note ? ' — ' + limpar(a.note).slice(0, 300) : '')).join('\n');
  const anteriores = (e.anteriores || []).map((i) => i.json || i).filter((r) => r && r.texto && r.id !== row.id && /ENVIADA|PRONTA/.test(r.status || ''))
    .sort((a, b) => Date.parse(a.criado_em) - Date.parse(b.criado_em)).slice(-5)
    .map((r) => '- (' + r.tipo_msg + ') ' + r.texto).join('\n');

  const linhas = [];
  const add = (rot, v) => { if (v) linhas.push(rot + ': ' + v); };
  add('Nome do contato', nomeCompleto);
  add('Empresa', (org && org.name) || deal.title);
  add('Site da empresa', org && org.website);
  add('Cidade', cf(org, 'PD_ORG_CIDADE'));
  add('Serviço em negociação', cf(deal, 'PD_DEAL_SERVICO'));
  add('Escopo', cf(deal, 'PD_DEAL_ESCOPO'));
  add('Status do diagnóstico', cf(deal, 'PD_DEAL_DIAG_STATUS'));
  add('Link do diagnóstico', cf(deal, 'PD_DEAL_DIAG_LINK'));
  add('Link da proposta', cf(deal, 'PD_DEAL_PROPOSTA_LINK'));
  // Demais campos preenchidos no card (dores, segmento, temperatura etc.), com o nome do campo
  const usados = new Set(Object.keys(cfg).filter((k) => /^PD_/.test(k)).map((k) => cfg[k].valor));
  const defs = {};
  for (const f of (e.campos || [])) if (f && f.key) defs[f.key] = f;
  for (const [k, bruto] of Object.entries(deal.custom_fields || {})) {
    if (usados.has(k) || bruto === null || bruto === undefined || bruto === '') continue;
    const def = defs[k]; if (!def || !def.name) continue;
    let x = bruto; if (x && typeof x === 'object') x = x.value !== undefined ? x.value : null;
    if (x === null || x === undefined || x === '') continue;
    if (Array.isArray(def.options) && def.options.length) {
      const ids = String(x).split(',').map((s) => s.trim());
      const rot = ids.map((id) => (def.options.find((o) => String(o.id) === id) || {}).label).filter(Boolean);
      if (rot.length) x = rot.join(', ');
    }
    add(def.name, limpar(String(x)).slice(0, 400));
  }

  const voz = val('FUNIL_IA_VOZ', 'Escreva como a equipe comercial da ATOM Digital, de forma humana, próxima e direta.');
  const principios = val('FUNIL_IA_PRINCIPIOS', '');
  const roteiro = val('FUNIL_ROTEIRO_' + tipo, row.objetivo || '');
  const remetente = val('FUNIL_REMETENTE', 'Thiago');
  const agenda = ok('FUNIL_LINK_AGENDA') ? val('FUNIL_LINK_AGENDA', '') : '';
  const cases = ok('FUNIL_CASES') ? val('FUNIL_CASES', '') : '';
  const hojeL = new Date(agoraMs - 3 * 3600000);
  const diasSemana = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado'];
  const hoje = diasSemana[hojeL.getUTCDay()] + ', ' + hojeL.toISOString().slice(8, 10) + '/' + hojeL.toISOString().slice(5, 7) + '/' + hojeL.toISOString().slice(0, 4) + ', ' + hojeL.toISOString().slice(11, 16);
  const reuniao = reuniaoRef || reuniaoFutura;
  const prompt = [
    voz,
    '',
    'PRINCÍPIOS DE VENDA (aplique sem citar autores nem nomes de técnicas):',
    principios,
    '',
    'AGORA: ' + hoje + ' (horário de Brasília). Quem assina e fala em primeira pessoa: ' + remetente + ', da ATOM.',
    'TIPO DESTA MENSAGEM: ' + tipo,
    '',
    'ROTEIRO DESTA MENSAGEM — siga a estrutura e a intenção, mas escreva com naturalidade. Troque cada [COLCHETE] por um dado real do contexto abaixo. Se o dado não existir, reescreva a frase sem ele (nunca invente, nunca deixe colchete). Instruções entre parênteses são para você, não vão na mensagem:',
    roteiro,
    '',
    'DADOS DO CLIENTE:',
    linhas.join('\n') || '(poucos dados cadastrados)',
    reuniao ? 'Reunião agendada: ' + fmtQuando(reuniao.due_date, reuniao.due_time) + (reuniao.conference_meeting_url ? ' — link: ' + reuniao.conference_meeting_url : '') : 'Reunião agendada: nenhuma',
    agenda ? 'Link de agenda para o cliente escolher horário: ' + agenda : 'Link de agenda: não há (proponha duas opções de dia útil a partir de amanhã)',
    '',
    'CASES REAIS QUE PODEM SER CITADOS:',
    cases || '(nenhum cadastrado — não cite cases, clientes nem resultados de terceiros)',
    '',
    'NOTAS DO NEGÓCIO (mais recentes primeiro; inclui diagnóstico e resumo de reuniões quando houver):',
    notas || '(sem notas)',
    '',
    'ATIVIDADES JÁ FEITAS PELO VENDEDOR:',
    feitas || '(nenhuma registrada)',
    '',
    'CONVERSA NO WHATSAPP (Zayra):',
    e.conversa || '(histórico ainda não conectado)',
    '',
    'MENSAGENS QUE JÁ ENVIAMOS A ESTE CLIENTE (não repita frases, ganchos nem aberturas):',
    anteriores || '(nenhuma)',
    '',
    'REGRAS FINAIS:',
    '- Chame o cliente pelo primeiro nome' + (primeiroNome ? ' (' + primeiroNome + ')' : ' se souber; se não souber, use um cumprimento neutro, sem nome') + '.',
    '- Se as notas ou atividades mostram uma conversa recente, parta dela em vez de seguir o roteiro ao pé da letra.',
    '- De 2 a 5 linhas, no máximo uma pergunta e no máximo um emoji.',
    '- Não invente dados, números, prazos, preços, cases nem resultados. Não prometa posição no Google.',
    '- Sem colchetes, variáveis, marcações, aspas em volta ou assinatura longa.',
    '- Responda SOMENTE com o texto final da mensagem, pronto para enviar.',
  ].join('\n');

  const zayraLiberada = ok('ZAYRA_MECANISMO') && val('ZAYRA_MECANISMO', '') === 'HTTP_WEBHOOK' && ok('ZAYRA_ENDPOINT_URL') && val('MODO_EXECUCAO', 'SIMULACAO').toUpperCase() !== 'SIMULACAO';
  return Object.assign(base, {
    cancelar: false, prompt, telefone, primeiro_nome: primeiroNome, deal_titulo: deal.title, owner_id: deal.owner_id,
    person_id: pessoa ? pessoa.id : null, org_id: deal.org_id || null,
    canal: zayraLiberada && telefone ? 'ZAYRA' : 'VENDEDOR',
    zayra_endpoint: zayraLiberada ? val('ZAYRA_ENDPOINT_URL', '') : '',
    motivo_vendedor: zayraLiberada ? (telefone ? '' : 'Contato sem telefone cadastrado') : 'Zayra ainda não conectada',
  });
}


const r = montarContexto({
  config: $('Ler configuração').all(),
  msg: $('Uma por vez').first().json,
  deal: $('Buscar negócio').first().json,
  pessoa: $('Buscar pessoa').first().json,
  org: $('Buscar empresa').first().json,
  notas: $('Buscar notas').first().json,
  atividades: $('Buscar atividades feitas').first().json,
  anteriores: $('Mensagens anteriores').all().filter((i) => i.json),
  campos: (($('Campos do negócio').first().json || {}).data) || [],
  agora: Date.now(),
});
if (r.prompt) r.prompt = r.prompt.replace(/[{}]/g, '');
return [{ json: r }];

// ===== Preparar saída =====
const ROTULO = { ABORDAGEM_1: 'Abordagem 1 (diagnóstico)', ABORDAGEM_2: 'Abordagem 2', ABORDAGEM_3: 'Abordagem 3 (última)', ETAPA_7: 'Contato feito', ETAPA_29: 'Diagnóstico em preparação', ETAPA_8: 'Diagnóstico enviado', LEMBRETE_VESPERA: 'Lembrete da reunião (véspera)', DIAG_FUP_1: 'Follow-up 1 do diagnóstico', DIAG_FUP_2: 'Follow-up 2 do diagnóstico', ETAPA_9: 'Pós-reunião', PROPOSTA_ENVIADA: 'Envio da proposta', PROP_FUP_1: 'Follow-up 1 da proposta', PROP_FUP_2: 'Follow-up final da proposta', ETAPA_28: 'Proposta aceita', LEMBRETE_ASSINATURA: 'Lembrete de assinatura', ETAPA_11: 'Boas-vindas', POS_INDICACAO_30: 'Pedido de indicação' };
function prepararSaida(ctx, textoIA, agora) {
  let t = String(textoIA || '').trim().replace(/^["“”']+|["“”']+$/g, '').replace(/^(mensagem|texto)\s*:\s*/i, '').trim();
  const valido = t.length >= 15 && !/[{}\[\]]/.test(t);
  const hoje = new Date(agora - 3 * 3600000).toISOString().slice(0, 10);
  const rot = ROTULO[ctx.tipo_msg] || ctx.tipo_msg;
  return {
    row_id: ctx.row_id, texto: t, valido, canal: valido ? ctx.canal : 'VENDEDOR',
    zayra: { request_id: 'msg-' + ctx.row_id, action: 'ENVIAR_MENSAGEM', pipedrive_deal_id: String(ctx.deal_id), pipedrive_person_id: String(ctx.person_id || ''), recipient_phone: String(ctx.telefone || '').replace(/[^\d+]/g, ''), message_text: t, message_type: ctx.tipo_msg },
    atividade: {
      subject: '[Funil] 💬 ' + rot + ' — ' + ctx.deal_titulo, type: 'task', owner_id: ctx.owner_id, deal_id: Number(ctx.deal_id),
      participants: ctx.person_id ? [{ person_id: ctx.person_id, primary: true }] : undefined, due_date: hoje,
      note: (valido ? 'Mensagem personalizada pela IA, pronta para enviar' + (ctx.telefone ? ' para ' + ctx.telefone : '') + ':<br><br>' + t.replace(/\n/g, '<br>')
        : 'A IA não conseguiu gerar uma mensagem válida. Escreva manualmente com o objetivo: ' + (ctx.objetivo || rot)) +
        '<br><br><i>' + (ctx.motivo_vendedor ? 'Enviar manualmente: ' + ctx.motivo_vendedor + '.' : '') + ' Marque como feita após enviar.</i>',
    },
  };
}


return [{ json: prepararSaida($('Montar contexto').first().json, $input.first().json.text, Date.now()) }];

const s = $('Preparar saída').first().json;
const r = $input.first().json || {};
let status; let erro = '';
if (s.canal === 'ZAYRA') {
  const ok = r.statusCode >= 200 && r.statusCode < 300;
  status = ok ? 'ENVIADA_ZAYRA' : 'ERRO';
  if (!ok) erro = 'Zayra HTTP ' + r.statusCode;
} else {
  status = r.success ? 'PRONTA_VENDEDOR' : 'ERRO';
  if (!r.success) erro = JSON.stringify(r).slice(0, 300);
}
return [{ json: { row_id: s.row_id, texto: s.texto, status, canal_saida: s.canal, enviado_em: new Date().toISOString(), erro } }];
